// THE FREEZE, PROVEN — and it is proven against the real corpus rather than
// against a fixture generated by the thing under test.
//
// `getEngine(rev)` now dispatches over more than one rev, which is the point at
// which "old replays verify forever" stops being a design note and becomes a
// claim somebody can break. The claim is narrow and absolute: a rev-4 replay
// recorded before rev 5 existed must still re-simulate to a BIT-IDENTICAL
// periodic hash chain, every hash, not just the same finishing time.
//
// Every file under `replays/` is in scope: the scripted pilot's runs, the
// solver's solutions, and the runs exported by hand out of the client. A
// synthetic replay generated inside this test would prove almost nothing —
// it would be recorded and verified by the same code in the same process, so
// it could only ever detect a non-deterministic sim, never a changed one. The
// files on disk were written by a build that no longer exists, which is exactly
// what makes them evidence.
//
// WHAT FAILING HERE MEANS. Not "regenerate the fixtures". It means a physics
// edit reached rev 4, and the edit is wrong: rev 4 is the live rev, people have
// times on it, and the whole reason rev 5 lives in a directory of its own is so
// that developing it cannot do this. The message names the file and the first
// frame that diverged.
import { describe, it, expect } from 'vitest';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { parseReplayFile } from './replay.ts';
import type { ReplayFile } from './replay.ts';
import { getEngine, hasEngine, REVS, SIM_REV, LATEST_REV } from './rev.ts';

const REPLAY_DIR = fileURLToPath(new URL('../../replays/', import.meta.url));

interface Loaded {
  name: string;
  file: ReplayFile;
}

function loadAll(): Loaded[] {
  return readdirSync(REPLAY_DIR)
    .filter((f) => f.endsWith('.replay.json'))
    .sort()
    .map((name) => ({ name, file: parseReplayFile(JSON.parse(readFileSync(join(REPLAY_DIR, name), 'utf8'))) }));
}

const ALL = loadAll();
const RUNNABLE = ALL.filter((r) => hasEngine(r.file.simRev));
const ORPHANED = ALL.filter((r) => !hasEngine(r.file.simRev));

describe('the replay corpus', () => {
  it('is large enough to be evidence', () => {
    // Guards every assertion below against passing because the scan found
    // nothing — the classic way a corpus test rots into a no-op.
    expect(ALL.length).toBeGreaterThan(30);
    expect(RUNNABLE.length).toBeGreaterThan(20);
  });

  it('covers the live rev and both tools that produce runs', () => {
    const onLive = ALL.filter((r) => r.file.simRev === SIM_REV);
    expect(onLive.length).toBeGreaterThan(20);
    expect(onLive.some((r) => r.name.includes('solve'))).toBe(true);
    expect(onLive.some((r) => r.name.includes('pilot'))).toBe(true);
  });

  it('is self-contained: every file carries its own level and bike', () => {
    const missing = ALL.filter((r) => r.file.level === undefined || r.file.spec === undefined).map((r) => r.name);
    // A replay without its level is a replay that can only be verified while
    // the level file it was recorded against still exists unedited, which is
    // not a guarantee anyone can make about a level set still being authored.
    expect(missing).toEqual([]);
  });
});

describe('frozen revs still verify', () => {
  for (const { name, file } of RUNNABLE) {
    it(`${name} (rev ${file.simRev})`, () => {
      const engine = getEngine(file.simRev);
      expect(engine.rev).toBe(file.simRev);

      // Compiled and parsed by the REV'S OWN loader, not by whatever the live
      // build happens to have. Arc tessellation and winding normalisation
      // decide what the bike hits, so they belong to the rev as much as
      // step.ts does.
      const level = engine.parseLevel(file.level);
      const spec = engine.parseSpec(file.spec);
      expect(engine.specHash(spec)).toBe(file.specHash);
      expect(level.simHash).toBe(file.simHash);

      // The hash chain has to be COMPLETE, or `verifyReplay` would be checking
      // an empty list and reporting success. This is the assertion that makes
      // the rest of the test mean "bit-identical" rather than "finished in the
      // same time".
      expect(file.hashEvery).toBeGreaterThan(0);
      const expectedHashes = Math.floor(file.frames / file.hashEvery);
      expect(file.hashes.length).toBe(expectedHashes);
      expect(file.hashes.length).toBeGreaterThan(0);

      const res = engine.verifyReplay(level, spec, file);
      const where =
        res.atFrame === undefined
          ? (res.reason ?? '')
          : `frame ${res.atFrame}: expected ${res.expected}, got ${res.actual}`;
      expect(res.ok, where).toBe(true);
      expect(res.timeTicks).toBe(file.timeTicks);
      expect(res.finished).toBe(file.finished);
      expect(res.dead).toBe(file.dead);
      expect(res.applesLeft).toBe(file.applesLeft);
    });
  }
});

describe('revs this build does not have', () => {
  it('are refused by name rather than run on the wrong physics', () => {
    // Rev 3 replays are still on disk and still parse — parsing and
    // compatibility are deliberately separate, so an old file reads as "another
    // rev" and never as "corrupt". What must not happen is one of them quietly
    // running on rev 4's code.
    for (const { file } of ORPHANED) {
      expect(REVS).not.toContain(file.simRev);
      expect(() => getEngine(file.simRev)).toThrow(/unknown SIM_REV/);
    }
  });

  it('every rev this build claims is actually reachable', () => {
    for (const rev of REVS) expect(getEngine(rev).rev).toBe(rev);
    expect(REVS).toContain(SIM_REV);
    expect(REVS).toContain(LATEST_REV);
    // The live rev is never ahead of the newest one, and shipping on the newest
    // rev is a decision rather than a default: today they differ on purpose.
    expect(SIM_REV).toBeLessThanOrEqual(LATEST_REV);
  });
});
